import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Computes C(m,n) = sum_k A(m,k) * B(k,n)
// mA is presented as (M,K), mB is presented as (N,K) (a transposed view of the
// physically (K,N) row-major B), and cute::gemm(sA_mk, sB_nk, C_mn) naturally
// performs the (M,K) x (N,K) -> (M,N) contraction along the last (K) mode.
template <class ProblemShape,
          class TA, class AStride,
          class TB, class BStride,
          class TC, class CStride>
__global__ static void
gemm_tallskinny_device(ProblemShape shape_MNK,
                        TA const* A, AStride dA,
                        TB const* B, BStride dB,
                        TC      * C, CStride dC)
{
  using namespace cute;

  Tensor mA = make_tensor(make_gmem_ptr(A),
                           make_shape(get<0>(shape_MNK), get<2>(shape_MNK)), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B),
                           make_shape(get<1>(shape_MNK), get<2>(shape_MNK)), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C),
                           make_shape(get<0>(shape_MNK), get<1>(shape_MNK)), dC); // (M,N)

  // Tile: BLK_M x BLK_N x BLK_K.  BLK_K == 32 matches the contraction dim
  // exactly for this tall-skinny problem so the K-loop below runs a single
  // iteration.
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});

  // Pad the K-dimension stride of the shared-memory tiles by one element.
  // BLK_K == 32 exactly matches the number of shared-memory banks, so the
  // default packed layout causes systematic bank conflicts when gemm()
  // reads column slices of sA/sB across all threads. Padding the stride
  // to 129/65 removes this alignment without altering the (M/N-contiguous)
  // majorness used for the coalesced global->shared copies.
  constexpr int PAD_A = 128 + 1;
  constexpr int PAD_B = 128 + 1;
  __shared__ TA smemA[PAD_A*32];
  __shared__ TB smemB[PAD_B*32];
  Tensor sA = make_tensor(make_smem_ptr(smemA),
                           make_layout(make_shape(Int<128>{}, Int<32>{}),
                                       make_stride(Int<1>{}, Int<PAD_A>{})));
  Tensor sB = make_tensor(make_smem_ptr(smemB),
                           make_layout(make_shape(Int<128>{}, Int<32>{}),
                                       make_stride(Int<1>{}, Int<PAD_B>{})));

  auto tC = make_layout(make_shape(Int<32>{}, Int<32>{}));
  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Vectorized (float4) global -> shared loads.  Each A-tile row segment of
  // BLK_K=32 contiguous elements and each B-tile row segment of BLK_N=128
  // contiguous elements is loaded with 128-bit transactions instead of the
  // scalar element-wise copies used previously, cutting the number of global
  // memory instructions by 4x while preserving the padded shared layout.
  int Kdim = int(get<2>(shape_MNK));
  int Ndim = int(get<1>(shape_MNK));
  int mA_local = threadIdx.x / 8;          // 0..127
  int kA4      = (threadIdx.x % 8) * 4;    // 0,4,...,28
  int kB_local = threadIdx.x / 32;         // 0..31
  int nB4      = (threadIdx.x % 32) * 4;   // 0,4,...,124
  int K_TILE_MAX = size<2>(gA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    const TA* A_row_base = A + (int64_t)blockIdx.x * 128 * Kdim + (int64_t)k_tile * 32;
    const TB* B_row_base = B + (int64_t)k_tile * 32 * Ndim + (int64_t)blockIdx.y * 128;
    float4 a4 = *reinterpret_cast<const float4*>(A_row_base + (int64_t)mA_local * Kdim + kA4);
    smemA[mA_local + (kA4 + 0) * PAD_A] = a4.x;
    smemA[mA_local + (kA4 + 1) * PAD_A] = a4.y;
    smemA[mA_local + (kA4 + 2) * PAD_A] = a4.z;
    smemA[mA_local + (kA4 + 3) * PAD_A] = a4.w;
    float4 b4 = *reinterpret_cast<const float4*>(B_row_base + (int64_t)kB_local * Ndim + nB4);
    smemB[(nB4 + 0) + kB_local * PAD_B] = b4.x;
    smemB[(nB4 + 1) + kB_local * PAD_B] = b4.y;
    smemB[(nB4 + 2) + kB_local * PAD_B] = b4.z;
    smemB[(nB4 + 3) + kB_local * PAD_B] = b4.w;
    __syncthreads();
    CUTE_UNROLL
    for (int kk = 0; kk < 32; ++kk) {
      float rA0 = tCsA(0,kk), rA1 = tCsA(1,kk), rA2 = tCsA(2,kk), rA3 = tCsA(3,kk);
      float rB0 = tCsB(0,kk), rB1 = tCsB(1,kk), rB2 = tCsB(2,kk), rB3 = tCsB(3,kk);
      tCrC(0,0) += rA0*rB0; tCrC(0,1) += rA0*rB1; tCrC(0,2) += rA0*rB2; tCrC(0,3) += rA0*rB3;
      tCrC(1,0) += rA1*rB0; tCrC(1,1) += rA1*rB1; tCrC(1,2) += rA1*rB2; tCrC(1,3) += rA1*rB3;
      tCrC(2,0) += rA2*rB0; tCrC(2,1) += rA2*rB1; tCrC(2,2) += rA2*rB2; tCrC(2,3) += rA2*rB3;
      tCrC(3,0) += rA3*rB0; tCrC(3,1) += rA3*rB1; tCrC(3,2) += rA3*rB2; tCrC(3,3) += rA3*rB3;
    }
    __syncthreads();
  }

  axpby(1.0f, tCrC, 0.0f, tCgC);
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  int M  = (int)A.size(0);
  int K  = (int)A.size(1);
  int Kb = (int)B.size(0);
  int N  = (int)B.size(1);
  TORCH_CHECK(K == Kb, "Inner dimensions of A and B must match");
  TORCH_CHECK(M % 128 == 0, "M must be a multiple of 128 for this kernel");
  TORCH_CHECK(N % 128 == 0, "N must be a multiple of 128 for this kernel");
  TORCH_CHECK(K % 32 == 0,  "K must be a multiple of 32 for this kernel");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // A is row-major (M,K): stride (K,1)
  auto dA = make_stride(K, Int<1>{});
  // B is row-major (K,N); viewed transposed as (N,K): stride (1,N)
  auto dB = make_stride(Int<1>{}, N);
  // C is row-major (M,N): stride (N,1)
  auto dC = make_stride(N, Int<1>{});

  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(1024);
  dim3 dimGrid(M/128, N/128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_tallskinny_device<<<dimGrid, dimBlock, 0, stream>>>(
      shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm = load_inline(
    name="cute_tallskinny_gemm",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Tall-skinny matrix multiplication C = A @ B implemented with a custom
    tiled CuTe GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A_f = A.contiguous().float() if A.dtype != torch.float32 else A.contiguous()
        B_f = B.contiguous().float() if B.dtype != torch.float32 else B.contiguous()
        return self._ext.cute_matmul(A_f, B_f)

